#!/bin/bash
set -e

echo "=== Installing Settings Page ==="
echo ""

# Backup existing app.html if not already
if [ ! -f /var/www/buildcalcpro/app.html.PRE_SETTINGS_BTN ]; then
    sudo cp /var/www/buildcalcpro/app.html /var/www/buildcalcpro/app.html.PRE_SETTINGS_BTN
    echo "✓ Backup: app.html.PRE_SETTINGS_BTN"
fi

# 1. Decode and write settings.html
echo ""
echo "=== Writing settings.html ==="
SETTINGS_B64=""
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
SETTINGS_B64+=''
echo "$SETTINGS_B64" | base64 -d | sudo tee /var/www/buildcalcpro/settings.html > /dev/null
sudo chown www-data:www-data /var/www/buildcalcpro/settings.html
echo "✓ settings.html written"

# 2. Add /settings route to Nginx
echo ""
echo "=== Adding /settings to Nginx ==="
if ! sudo grep -q "location = /settings" /etc/nginx/sites-available/buildcalcpro; then
    sudo python3 - <<'NGINX_EOF'
with open('/etc/nginx/sites-available/buildcalcpro', 'r') as f:
    cfg = f.read()

new_routes = """    location = /settings { try_files /settings.html =404; }
    location = /settings/ { try_files /settings.html =404; }
    location = /app { try_files /app.html =404; }"""

old_route = "    location = /app { try_files /app.html =404; }"

if old_route in cfg and "location = /settings" not in cfg:
    cfg = cfg.replace(old_route, new_routes, 1)
    with open('/tmp/nginx_bcp.conf', 'w') as f:
        f.write(cfg)
    import subprocess
    subprocess.run(['sudo', 'cp', '/tmp/nginx_bcp.conf', '/etc/nginx/sites-available/buildcalcpro'])
    print('OK: /settings route added to Nginx')
else:
    print('OK: /settings route already exists or /app route not found')
NGINX_EOF
    sudo nginx -t && sudo systemctl reload nginx
    echo "✓ Nginx reloaded with /settings route"
else
    echo "✓ Nginx already has /settings"
fi

# 3. Add Settings button to app.html header
echo ""
echo "=== Adding Settings button to app header ==="
sudo python3 - <<'PYEOF2'
with open('/var/www/buildcalcpro/app.html', 'r') as f:
    content = f.read()

# Check if already added
if 'href="/settings"' in content or "href='/settings'" in content:
    print("ALREADY: Settings button already in app")
    import sys
    sys.exit(0)

# Find the Sign Out button and add Settings button BEFORE it
anchor = '<button onClick={()=>{if(confirm("Sign out?")){localStorage.removeItem("bc_token");localStorage.removeItem("bc_user");window.location.href="/login";}}}'

settings_btn = '<a href="/settings" style={{padding:"6px 10px",fontSize:12,background:"transparent",border:"1px solid #4b5563",color:"#9ca3af",borderRadius:6,cursor:"pointer",fontFamily:"inherit",marginLeft:"4px",textDecoration:"none",display:"inline-flex",alignItems:"center"}} title="Company Settings">Settings</a>\n                ' + anchor

if anchor in content:
    content = content.replace(anchor, settings_btn, 1)
    with open('/var/www/buildcalcpro/app.html', 'w') as f:
        f.write(content)
    print("OK: Settings button added to app header")
else:
    print("WARN: Could not find Sign Out anchor - settings button NOT added")
PYEOF2

echo ""
echo "=== Verification ==="
ls -la /var/www/buildcalcpro/settings.html
SETTINGS_SIZE=$(stat -c%s /var/www/buildcalcpro/settings.html 2>/dev/null || echo "0")
echo "Settings page size: $SETTINGS_SIZE bytes"
echo ""
echo "✓ DONE - Visit https://buildcalcpro.club/settings (must be logged in)"
